        for j in range (3):
            if board[i][j] != 'X' and board[i][j] != 'O':
                return False

# Function to perform the basic AI operations to play tic-tac-toe
def play_tic_tac_toe (board):
    # Check if board is full or not 
    if board_played (board) == False : 
        # Generate random position
        row = random.randint (0,3) 
        col = random.randint (0,3) 

        # Check the safe position 
        if (board[row][col] != 'X' and board[row][col] != 'O'): 
            board[row][col] = 'O'
        else: 
            # Call function again 
            play_tic_tac_toe (board)
    else: 
        print ("Board Played")

def check_prime(num): 

  # Check for negative or zero input 
  if num <= 0: 
    return False

  # Check for 1  
  if num == 1: 
    return False

  # Check if the number is divisible by any number between 2 and n-1  
  for i in range(2, num): 
    if num % i == 0: 
      return False

  # If there is no divisor, the number is prime  
  return True

The following program sorts an array of numbers in ascending order: 

def sort_array(array): 
    for i in range(len(array)): 
        min_index = i 
        for j in range(i+1, len(array)): 
            if array[min_index] > array[j]: 
                min_index = j 

        array[i], array[min_index] = array[min_index], array[i] 
    return array 

print(sort_array([4, 2, 5, 1, 3]))  # [1, 2, 3, 4, 5]

def sort_ascending(arr): 
    for i in range(len(arr)): 
        for j in range(i+1, len(arr)): 
            if arr[i] > arr[j]: 
                arr[i], arr[j] = arr[j], arr[i] 
    return arr

